mkdir -p src/fastsim
cat > src/fastsim/vsim_core.h <<'EOF'
#pragma once

// VsimCore -- the Verilated core as a FastSim module (integration plan S1).
//
// vsim's own binary owns the SystemC kernel: sc_main builds a Simulator, then
// steps it one clock period at a time with sc_start (src/main.cpp). FastSim
// works the other way round: its sc_main loads a Lua platform, calls sc_start()
// exactly once, and every model lives inside the kernel for the whole run.
//
// Those two are the same simulation with the ownership inverted, and this
// module is the inversion. It holds the Simulator that main.cpp would have
// held, and performs main.cpp's sequence -- settle, load the ELF, reset, run --
// inside one SC_THREAD, where advancing a cycle is wait() and not sc_start.
// Everything mechanism-specific about that lives in platform/cycle_clock.hpp;
// this file only decides which one applies (ScWaitClock, always: a module is
// never the kernel's owner).
//
// Scope is cycle mode: the devices stay vsim's own, exactly as they are today.
// Sharing one device set with QEMU is S2, and needs the router binding this
// module deliberately does not yet declare.

#include "cpu_config.hpp"     // VSIM_CPU_INTERFACE_CLASS
#include "platform/cycle_clock.hpp"
#include "simulator.hpp"

#include <cci_configuration>
#include <systemc>

#include <cstdint>
#include <string>

class VsimCore : public sc_core::sc_module
{
public:
  using CPU = VSIM_CPU_INTERFACE_CLASS;

  // Inputs. These are the cycle-mode subset of main.cpp's options; the Lua
  // platform file is where they are set, which is what makes a mode a
  // platform rather than a process recipe.
  cci::cci_param<std::string> p_elf_file;
  cci::cci_param<uint64_t> p_max_cycles;
  cci::cci_param<uint32_t> p_mem_latency;

  // Outputs. `guest_exit_status` is named for the scan FastSim's sc_main
  // already does over broker parameters, so the engine's exit code reaches the
  // process exit code with no new mechanism (see multi_arch_toplevel.cpp).
  cci::cci_param<uint64_t> p_cycles;
  cci::cci_param<int> p_guest_exit_status;

  SC_HAS_PROCESS(VsimCore);
  explicit VsimCore(const sc_core::sc_module_name& name);

private:
  void drive();

  // A module is never the kernel's owner, so the loop yields rather than
  // starting the kernel. Declared before sim_ so it outlives every use.
  ScWaitClock cycle_clock_;
  Simulator<CPU> sim_;
};

extern "C" void module_register();
EOF
echo "header written: $(wc -l < src/fastsim/vsim_core.h) lines"

cd /home/nick/work/vsim_andesim
cat > src/fastsim/vsim_core.cc <<'EOF'
#include "fastsim/vsim_core.h"

#include "platform/memory_map.h"

#include <module_factory_registery.h>
#include <spdlog/sinks/stdout_color_sinks.h>
#include <spdlog/spdlog.h>

#include <stdexcept>

VsimCore::VsimCore(const sc_core::sc_module_name& name)
    : sc_core::sc_module{name},
      p_elf_file("elf_file", "", "Guest ELF to run from reset"),
      p_max_cycles("max_cycles", 0, "Cycle budget; 0 means no limit"),
      p_mem_latency("mem_latency", 1,
                    "Wait states SimpleMemory reports to the core, in cycles. "
                    "Matches vsim's --mem-latency default; see the note in "
                    "andesim tests/baseline/kernel_cycles.tsv before changing "
                    "it, because every recorded cycle count moves with it."),
      p_cycles("cycles", 0, "Cycles simulated, published when the run ends"),
      p_guest_exit_status("guest_exit_status", 0,
                          "The engine's exit code, carried out by FastSim's "
                          "sc_main parameter scan"),
      // Same construction as main.cpp's cycle-mode path: no shared mmap, so
      // RAM and its uncached alias come from the engine's own memory map.
      sim_("sim", std::span<uint8_t>{}, MemoryRegion{RAM_BASE, RAM_END},
           MemoryRegion{RAM_ALIAS_BASE, RAM_ALIAS_END})
{
  // main.cpp routes vsim's logs to stderr. Keep that: andesim lifts the one
  // number it shows the user out of this stream (driver/vsim_filter.hpp).
  spdlog::set_default_logger(spdlog::stderr_color_mt("stderr_logger"));
  spdlog::set_pattern("[%^%l%$] %v");

  SC_THREAD(drive);
}

// main.cpp's sequence, moved inside the kernel. The order is load-bearing:
// settling before load_elf and resetting after it is what the recorded cycle
// counts were measured against, so it is reproduced rather than tidied.
void VsimCore::drive()
{
  const std::string elf = p_elf_file;
  if (elf.empty())
    throw std::runtime_error(
      "VsimCore: elf_file is empty; cycle mode runs a guest ELF from reset");

  sim_.set_cycle_clock(cycle_clock_);
  sim_.set_mem_latency(p_mem_latency);

  // End of elaboration. main.cpp starts the kernel for zero time here; inside
  // the kernel the same settling is one delta, which is what advance() does.
  cycle_clock_.advance(sc_core::SC_ZERO_TIME);

  sim_.load_elf(elf, /*skip_memory_load=*/false);
  sim_.reset();

  const uint64_t budget = p_max_cycles;
  const int exit_code =
    budget == 0 ? sim_.run() : sim_.run(budget);

  sim_.cpu.final();

  const auto cycles = sim_.get_cycles();
  p_cycles = cycles;
  p_guest_exit_status = exit_code;

  // The line andesim scrapes for `--mode cycle`. Same text as main.cpp, so the
  // driver needs no second parser.
  spdlog::info("{} cycles simulated", cycles);

  // Nothing else in a cycle-mode platform has work left, and the clock would
  // otherwise keep the kernel runnable for ever.
  sc_core::sc_stop();
}

extern "C" void module_register() { GSC_MODULE_REGISTER_C(VsimCore); }
EOF
