=== sys_call.hpp head ===
#ifndef SYS_CALL_HPP
#define SYS_CALL_HPP

#include "picolib.hpp"

#include <fcntl.h>
#include <spdlog/spdlog.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <unistd.h>

#include <cerrno>
#include <cstdint>
#include <cstring>

#include <algorithm>
#include <vector>

// NOTE: this header is #include'd inside the SimControl class body
// (sim_control.hpp), so the functions here are member functions with implicit
// `this`. The helpers below are member functions for the same reason -- they
// reach `data_region`, which is a private SimControl member.

// Convert a guest VA to a host pointer. A VA inside the SimControl syscall
// window resolves into the device's own window_ storage (the uncached
// mailbox -- no RAM, no guest cache can shadow it). Any other VA resolves
// into data_region.data, subtracting whichever base (region or alias_region)
