  void b_transport(tlm::tlm_generic_payload& trans, sc_core::sc_time&)
  {
    Call call{};
    call.addr = trans.get_address();
    call.len = trans.get_data_length();
    call.streaming_width = trans.get_streaming_width();
    call.cmd = trans.get_command();
    call.be_len = trans.get_byte_enable_length();

    auto* ptr = trans.get_data_ptr();
    for (unsigned i = 0; i < call.len; ++i)
      call.data[i] = ptr[i];

    if (call.be_len > 0 && trans.get_byte_enable_ptr()) {
      auto* be_ptr = trans.get_byte_enable_ptr();
      for (unsigned i = 0; i < call.be_len; ++i)
        call.be[i] = be_ptr[i];
    }

    calls.push_back(call);

    if (fail_on_call != 0 && calls.size() == fail_on_call) {
