// FastSim's side of the road out: records what arrives, on each road.
struct Host32 : sc_core::sc_module
{
  tlm_utils::simple_target_socket<Host32, 32> socket{"socket"};
  std::vector<uint64_t> timed_addrs;
  std::vector<std::pair<uint64_t, unsigned>> debug_writes;

  explicit Host32(const sc_core::sc_module_name& name)
      : sc_core::sc_module{name}
  {
    socket.register_b_transport(this, &Host32::b_transport);
    socket.register_transport_dbg(this, &Host32::transport_dbg);
  }

  void b_transport(tlm::tlm_generic_payload& gp, sc_core::sc_time&)
  {
    timed_addrs.push_back(gp.get_address());
    gp.set_response_status(tlm::TLM_OK_RESPONSE);
  }

  unsigned transport_dbg(tlm::tlm_generic_payload& gp)
  {
    debug_writes.emplace_back(gp.get_address(), gp.get_data_length());
    return gp.get_data_length();
  }
};

// Stands in for the CPU's AXI-to-TLM bridge: one initiator on the interconnect.
struct Core256 : sc_core::sc_module
{
  tlm_utils::simple_initiator_socket<Core256, 256> socket{"socket"};

  explicit Core256(const sc_core::sc_module_name& name)
      : sc_core::sc_module{name}
  {}

  void store_u32(uint64_t addr, uint32_t value)
  {
    std::array<uint8_t, 4> bytes{
      static_cast<uint8_t>(value), static_cast<uint8_t>(value >> 8),
      static_cast<uint8_t>(value >> 16), static_cast<uint8_t>(value >> 24)};
    tlm::tlm_generic_payload gp;
    gp.set_command(tlm::TLM_WRITE_COMMAND);
    gp.set_address(addr);
    gp.set_data_ptr(bytes.data());
    gp.set_data_length(bytes.size());
    gp.set_streaming_width(bytes.size());
    gp.set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
    sc_core::sc_time delay = sc_core::SC_ZERO_TIME;
    socket->b_transport(gp, delay);
    CHECK(gp.get_response_status() == tlm::TLM_OK_RESPONSE);
  }
};

