/* Hello on the AE350 device set, on the RTL core, with nothing under it: no
 * runtime, no libc, one hart.
 *
 * Console: UART2. The ATCUART100 puts its 16550 registers at +0x20 with a
 * 4-byte stride, so THR is 0xf0300020 and LSR 0xf0300034 -- the same two
 * registers the andesim runtime's console uses. On the FastSim platform they
 * are served by Uart16550V2 (reg_shift = 2) through the router.
 *
 * Exit: one store of the exit code to SimControl's exit register. SimControl
 * stays inside VsimCore, and the run loop polls it, so this is what ends the
 * simulation and becomes the process exit code.
 */
#include <stdint.h>

#define REG(addr) (*(volatile uint32_t*) (addr))

#define UART2_THR 0xf0300020u
#define UART2_LSR 0xf0300034u
#define LSR_THRE 0x20u
#define SIM_EXIT 0xe0080000u

static void uart_putc(char c)
{
  while (!(REG(UART2_LSR) & LSR_THRE)) {
  }
  REG(UART2_THR) = (uint8_t) c;
}

static void uart_puts(const char* s)
{
  for (; *s; ++s)
    uart_putc(*s);
}

void hello_main(void)
{
  uart_puts("hello from vsim on AE350\n");
  REG(SIM_EXIT) = 0;
  for (;;) {
  }
}

/* Reset lands here on every hart (the reset vector is this ELF's entry). Hart
 * 0 gets a stack and speaks; the others sleep. */
__attribute__((naked, section(".text.init"))) void _start(void)
{
  __asm__ volatile(
    "csrr t0, mhartid\n"
    "bnez t0, 1f\n"
    "la   sp, _stack\n"
    "call hello_main\n"
    "1:   wfi\n"
    "j    1b\n");
}
