// UARTs are inside. HostedPlatform is the FastSim module: nothing here owns
// those regions, and every address no internal device claims leaves through
// one socket to the host's router.
template<typename CONFIG>
class PlatformBase : public sc_core::sc_module
{
public:
  static constexpr size_t data_width = CONFIG::data_width;
  static constexpr size_t dmi_addr_width = CONFIG::dmi_addr_width;
  static constexpr size_t dmi_data_width = CONFIG::dmi_data_width;

  ahb::manager<dmi_addr_width, dmi_data_width> dmi{"dmi"};

  // CPU signals
  sc_core::sc_clock clk{"clk", sc_core::sc_time{1, sc_core::SC_NS}};
  sc_core::sc_signal<sc_dt::sc_uint<CONFIG::num_cores>> resetn;
  std::array<sc_core::sc_signal<vlpin<CONFIG::valen>>, CONFIG::num_cores>
    reset_vector;
  sc_core::sc_signal<bool> wfi_signal;
  sc_core::sc_signal<sc_dt::sc_uint<31>> int_trigger;

  ahb::signals<CONFIG::dmi_addr_width, CONFIG::dmi_data_width> dmi_signals{};

  jtag_dtm dtm{"dtm", dmi};

  Interconnect<data_width> interconnect{"interconnect"};

  SMU<data_width> smu{
    "smu", {SMU_BASE, SMU_END}, CONFIG::num_cores, CONFIG::has_shared_cache};

  SimControl<data_width> sim_control{"sim_control",
                                     {SIM_CONTROL_BASE, SIM_CONTROL_END},
                                     int_trigger,
                                     clk};

  // The ELF loader's road into guest memory: a debug write through the
  // interconnect, so the bytes land wherever the address routes -- in
  // SimpleMemory here, in a gs_memory beyond the router on the hosted
  // platform. The loader never holds a pointer to RAM.
  void write(uint64_t addr, std::span<const uint8_t> bytes)
  {
    if (bytes.size() > std::numeric_limits<unsigned>::max())
      throw std::invalid_argument("platform: write larger than one TLM payload");
    tlm::tlm_generic_payload gp;
    gp.set_command(tlm::TLM_WRITE_COMMAND);
    gp.set_address(addr);
    // TLM's payload is not const-aware; a write never touches the buffer.
    gp.set_data_ptr(const_cast<uint8_t*>(bytes.data()));
    gp.set_data_length(static_cast<unsigned>(bytes.size()));
    gp.set_streaming_width(static_cast<unsigned>(bytes.size()));
    const auto moved = loader_->transport_dbg(gp);
    if (moved != bytes.size())
      throw std::runtime_error(
        fmt::format("platform: {} of {} bytes written at {:#x}: no memory "
                    "owns that address",
