           std::span<uint8_t> ram_buffer = {},
           MemoryRegion ram_region = {RAM_BASE, RAM_END},
           MemoryRegion ram_alias_region = {RAM_ALIAS_BASE, RAM_ALIAS_END})
      : Base{name},
        main_memory("main_memory", ram_region, ram_alias_region, ram_buffer)
  {
    this->interconnect.bind_target(this->main_memory.socket,
                                   this->main_memory.region);
    this->interconnect.bind_target(this->main_memory.socket,
                                   this->main_memory.alias_region);
    this->interconnect.bind_target(this->uart1.socket, this->uart1.region);
    this->interconnect.bind_target(this->uart2.socket, this->uart2.region);
  }
};

// The FastSim module: nothing here owns RAM or the UARTs. Every address no
// internal device claims leaves through `bridge`, a width adapter from the
// core's bus to the host's 32-bit TLM sockets, and the host routes it. The
// road out is bridge.isck; VsimCore binds it to the socket the Lua platform
// names.
template<typename CONFIG>
class HostedPlatform : public PlatformBase<CONFIG>
{
public:
  using Base = PlatformBase<CONFIG>;
  using Base::data_width;
  static constexpr size_t host_width = 32;

  socket_width_adapter<data_width, host_width> bridge{"bridge"};

  explicit HostedPlatform(const sc_core::sc_module_name& name = "platform")
      : Base{name}
  {
    this->interconnect.bind_default_target(this->bridge.tsck);
  }
};
