  // already does over broker parameters, so the engine's exit code reaches the
  // process exit code with no new mechanism (see multi_arch_toplevel.cpp).
  cci::cci_param<uint64_t> p_cycles;
  cci::cci_param<int> p_guest_exit_status;

  // The road out: every access the core makes that no internal device serves.
  // 32 is FastSim's TLM socket width; the platform's bridge adapts the core's.
  // `initiator_socket = { bind = "&router.target_socket" }` in Lua.
